from collections import deque

def separate_paren_groups(paren_string: str) -> List[str]:
    def dfs(opening, paren_string, groups):
        if not paren_string:
            return groups

        open_paren = paren_string[0]
        if open_paren == '(':
            dfs(opening + '(', paren_string[1:], groups)
        elif open_paren == ')' and opening:
            if open_paren == closing(opening):
                dfs(opening[:-1], paren_string[1:], groups + [opening])
            else:
                dfs(opening, paren_string[1:], groups)

    def closing(opening):
        return ')' if opening == '(' else '(' if opening[-1] == '(' else None

    groups = []
    dfs('', paren_string, [])
    return groups

```

