from collections import defaultdict

def fibfib(n: int) -> int:
    fib_cache = defaultdict(lambda: None)

    def fib_rec(n):
        if n == 0 or n == 1:
            return 0
        elif n == 2:
            return 1
        elif fib_cache[n] is not None:
            return fib_cache[n]
        else:
            result = fib_rec(n - 1) + fib_rec(n - 2) + fib_rec(n - 3)
            fib_cache[n] = result
            return result

